describe('Table Row Numbers Feature', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('table').should('be.visible');
  });

  it('should display row numbers in the first column of the table', () => {
    cy.get('table tbody tr').each(($row, index) => {
      cy.wrap($row)
        .find('td')
        .first()
        .should('contain', (index + 1).toString());
    });
  });

  it('should display correct sequential row numbers for multiple rows', () => {
    cy.get('table tbody tr').should('have.length.greaterThan', 0);

    cy.get('table tbody tr').each(($row, index) => {
      const expectedRowNumber = index + 1;
      cy.wrap($row)
        .find('td')
        .first()
        .invoke('text')
        .then((text) => {
          expect(parseInt(text.trim())).to.equal(expectedRowNumber);
        });
    });
  });

  it('should maintain row numbers when table is sorted', () => {
    cy.get('table thead th').first().click();
    cy.wait(500);

    cy.get('table tbody tr').each(($row, index) => {
      cy.wrap($row)
        .find('td')
        .first()
        .should('contain', (index + 1).toString());
    });
  });

  it('should handle empty table gracefully', () => {
    cy.get('table tbody tr').then(($rows) => {
      if ($rows.length === 0) {
        cy.get('table tbody').should('be.empty');
      } else {
        cy.get('table tbody tr').first().find('td').first().should('contain', '1');
      }
    });
  });

  it('should display row numbers with proper alignment in first column', () => {
    cy.get('table tbody tr').first().find('td').first().should(($cell) => {
      expect($cell).to.have.css('text-align');
      expect($cell.text()).to.match(/^\d+$/);
    });
  });
});
